1	export interface Item {
2	  readonly type: string;
3	  readonly material?: string;
4	  readonly enchantment?: number;
5	  readonly cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  readonly op: "quote";
10	  readonly items: readonly Item[];
11	}
12	
13	export interface Damage {
14	  readonly itemType: string;
15	  readonly amount: number;
16	}
17	
18	export interface Incident {
19	  readonly cause: string;
20	  readonly damages: readonly Damage[];
21	}
22	
23	export interface ClaimStep {
24	  readonly op: "claim";
25	  readonly policy: number;
26	  readonly incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  readonly yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  readonly customer: Customer;
37	  readonly steps: readonly Step[];
38	}
39	
40	export interface QuoteResult {
41	  readonly premium: number;
42	}
43	
44	export interface ClaimResult {
45	  readonly payout: number;
46	  readonly remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  readonly results: readonly StepResult[];
53	}
